<?php
// update_vps.php — Self-extracting Update & Repair Pack
$bundle = [
  "includes/db.php" => "",
  "cron/start_publish.php" => "",
  "cron/cleanup.php" => "",
  "includes/fb_api.php" => "",
  "includes/drive_utils.php" => "",
  "campaign_detail.php" => "",
  "cron/publish_worker.php" => "",
  "actions/scan_old_phones.php" => "",
  "fix_mariadb_indexes.php" => "",
  "vps_deep_diagnostics.php" => "",
  "vps_master_fix.sh" => "",
];

echo "=== BẮT ĐẦU GIẢI NÉN VÀ CẬP NHẬT MÃ NGUỒN TẬN GỐC ===\n";
$target_dir = __DIR__;

foreach ($bundle as $rel_path => $b64) {
    $dest = $target_dir . '/' . $rel_path;
    $dir = dirname($dest);
    if (!is_dir($dir)) {
        @mkdir($dir, 0755, true);
    }
    file_put_contents($dest, base64_decode($b64));
    echo " [UPDATED] $rel_path\n";
}

echo "\n=== [1/4] CHẠY TỐI ƯU INDEX MARIADB ===\n";
require_once $target_dir . '/fix_mariadb_indexes.php';

echo "\n=== [2/4] TỐI ƯU THAM SỐ PHP-FPM (pm.max_children = 100) ===\n";
$fpm_confs = ['/www/server/php/74/etc/php-fpm.conf', '/www/server/php/74/etc/php-fpm.d/www.conf'];
foreach ($fpm_confs as $fc) {
    if (file_exists($fc)) {
        $c = file_get_contents($fc);
        $c = preg_replace('/pm\.max_children\s*=\s*\d+/', 'pm.max_children = 100', $c);
        $c = preg_replace('/pm\.start_servers\s*=\s*\d+/', 'pm.start_servers = 10', $c);
        $c = preg_replace('/pm\.min_spare_servers\s*=\s*\d+/', 'pm.min_spare_servers = 10', $c);
        $c = preg_replace('/pm\.max_spare_servers\s*=\s*\d+/', 'pm.max_spare_servers = 50', $c);
        file_put_contents($fc, $c);
        echo " [OK] Đã tối ưu pm.max_children = 100 trong $fc\n";
    }
}

echo "\n=== [3/4] DỌN DẸP TIẾN TRÌNH PHP-FPM MỒ CÔI & FILE LOCK ===\n";
@exec("pkill -9 -f php-fpm");
@unlink('/tmp/php-cgi-74.sock');
@unlink('/tmp/php-cgi-74.sock.lock');

echo "\n=== [4/4] KHỞI ĐỘNG LẠI DỊCH VỤ SẠCH SẼ ===\n";
@exec("/etc/init.d/sys_stats restart 2>/dev/null");
@exec("/etc/init.d/redis restart 2>/dev/null");
@exec("/etc/init.d/mysqld restart 2>/dev/null");
@exec("/etc/init.d/php-fpm-74 start 2>/dev/null");
@exec("/etc/init.d/httpd restart 2>/dev/null");

echo "\n=======================================================\n";
echo "   CẬP NHẬT VÀ TỐI ƯU TOÀN BỘ VPS HOÀN TẤT THÀNH CÔNG!\n";
echo "=======================================================\n";
